CREATE TABLE dbo.Settings ([key] nvarchar(80) NOT NULL PRIMARY KEY,[value] nvarchar(max) NOT NULL);
CREATE TABLE dbo.Admin_Users (email nvarchar(254) NOT NULL PRIMARY KEY,password_hash varchar(512) NOT NULL,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Admin_Usernames (username varchar(32) NOT NULL PRIMARY KEY,email nvarchar(254) NOT NULL UNIQUE REFERENCES dbo.Admin_Users(email));
CREATE TABLE dbo.Admin_Sessions (token_hash char(64) NOT NULL PRIMARY KEY,email nvarchar(254) NOT NULL REFERENCES dbo.Admin_Users(email),expires bigint NOT NULL);
CREATE INDEX IX_AdminSession_Expires ON dbo.Admin_Sessions(expires);
CREATE TABLE dbo.Customer_Registrations (id varchar(36) NOT NULL PRIMARY KEY,phone varchar(11) NOT NULL,first_name nvarchar(80) NOT NULL DEFAULT '',last_name nvarchar(80) NOT NULL DEFAULT '',phone_verified bit NOT NULL DEFAULT 0,created_at datetime2(3) NOT NULL,updated_at datetime2(3) NOT NULL);
CREATE INDEX IX_Customers_Phone ON dbo.Customer_Registrations(phone);
CREATE TABLE dbo.Customer_Accounts (phone varchar(11) NOT NULL PRIMARY KEY,registration_id varchar(36) NOT NULL UNIQUE REFERENCES dbo.Customer_Registrations(id),password_hash varchar(512) NOT NULL,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Customer_Sessions (token_hash char(64) NOT NULL PRIMARY KEY,registration_id varchar(36) NOT NULL REFERENCES dbo.Customer_Registrations(id),expires bigint NOT NULL);
CREATE INDEX IX_CustomerSession_Expires ON dbo.Customer_Sessions(expires);
CREATE TABLE dbo.Orders (id varchar(36) NOT NULL PRIMARY KEY,code varchar(20) NOT NULL UNIQUE,customer nvarchar(180) NOT NULL,phone varchar(11) NOT NULL,email nvarchar(254) NOT NULL DEFAULT '',title nvarchar(160) NOT NULL,service nvarchar(60) NOT NULL,spec nvarchar(max) NOT NULL,estimate bigint NOT NULL,final_price bigint NULL,status varchar(24) NOT NULL DEFAULT 'new',notes nvarchar(3000) NOT NULL DEFAULT '',admin_notes nvarchar(max) NOT NULL DEFAULT '',version int NOT NULL DEFAULT 1,created_at datetime2(3) NOT NULL,updated_at datetime2(3) NOT NULL,customer_id varchar(36) NULL REFERENCES dbo.Customer_Registrations(id),CONSTRAINT CK_OrderSpecJson CHECK(ISJSON(spec)=1),CONSTRAINT CK_OrderEstimate CHECK(estimate>=0));
CREATE INDEX IX_Orders_Created ON dbo.Orders(created_at DESC);
CREATE INDEX IX_Orders_Status ON dbo.Orders(status);
CREATE INDEX IX_Orders_Phone ON dbo.Orders(phone);
CREATE INDEX IX_Orders_Customer ON dbo.Orders(customer_id);
CREATE TABLE dbo.Events (id varchar(36) NOT NULL PRIMARY KEY,order_id varchar(36) NOT NULL REFERENCES dbo.Orders(id),status varchar(24) NOT NULL,note nvarchar(1000) NOT NULL,actor nvarchar(254) NOT NULL,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Files (id varchar(36) NOT NULL PRIMARY KEY,order_id varchar(36) NOT NULL REFERENCES dbo.Orders(id),object_key varchar(100) NOT NULL UNIQUE,name nvarchar(160) NOT NULL,size int NOT NULL,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Articles (id varchar(36) NOT NULL PRIMARY KEY,slug varchar(120) NOT NULL UNIQUE,title nvarchar(180) NOT NULL,excerpt nvarchar(400) NOT NULL,content nvarchar(max) NOT NULL,category nvarchar(60) NOT NULL,published bit NOT NULL DEFAULT 0,seo_title nvarchar(100) NOT NULL DEFAULT '',seo_description nvarchar(180) NOT NULL DEFAULT '',created_at datetime2(3) NOT NULL,updated_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Messages (id varchar(36) NOT NULL PRIMARY KEY,name nvarchar(180) NOT NULL,phone varchar(11) NOT NULL,subject nvarchar(160) NOT NULL,message nvarchar(max) NOT NULL,[read] bit NOT NULL DEFAULT 0,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Sms_Logs (id varchar(36) NOT NULL PRIMARY KEY,event_id varchar(36) NOT NULL UNIQUE,order_id varchar(36) NOT NULL REFERENCES dbo.Orders(id),phone varchar(11) NOT NULL,status varchar(24) NOT NULL,receipt varchar(80) NULL,error varchar(100) NULL,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Audit_Logs (id varchar(36) NOT NULL PRIMARY KEY,actor nvarchar(254) NOT NULL,action nvarchar(500) NOT NULL,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Rate_Limits ([key] varchar(100) NOT NULL PRIMARY KEY,[count] int NOT NULL,expires bigint NOT NULL);
CREATE TABLE dbo.Banner_Assets (id varchar(36) NOT NULL PRIMARY KEY,mime varchar(40) NOT NULL,size int NOT NULL,created_at datetime2(3) NOT NULL);
CREATE TABLE dbo.Tickets (id varchar(36) NOT NULL PRIMARY KEY,customer_id varchar(36) NOT NULL REFERENCES dbo.Customer_Registrations(id),subject nvarchar(160) NOT NULL,status varchar(24) NOT NULL DEFAULT 'open',created_at datetime2(3) NOT NULL,updated_at datetime2(3) NOT NULL,CONSTRAINT CK_TicketStatus CHECK(status IN ('open','awaiting_customer','closed')));
CREATE INDEX IX_Tickets_Customer ON dbo.Tickets(customer_id,updated_at DESC);
CREATE TABLE dbo.Ticket_Messages (id varchar(36) NOT NULL PRIMARY KEY,ticket_id varchar(36) NOT NULL REFERENCES dbo.Tickets(id),actor varchar(12) NOT NULL,message nvarchar(max) NOT NULL,created_at datetime2(3) NOT NULL,CONSTRAINT CK_TicketActor CHECK(actor IN ('customer','admin')));
CREATE INDEX IX_TicketMessages_Ticket ON dbo.Ticket_Messages(ticket_id,created_at);
CREATE TABLE dbo.Import_History (source_hash char(64) NOT NULL PRIMARY KEY,imported_at datetime2(3) NOT NULL);
